style.css:
/* Reset box-sizing only on html and body */
html, body {
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Body styling */
body {
  background-color: #f0f9f4 !important;
  color: #2e4d36 !important;
  font-family: 'Segoe UI', sans-serif !important;
  background-image: url('https://www.transparenttextures.com/patterns/floral-white.png'); /* light floral pattern */
  background-repeat: repeat;
}

/* Pinterest logo styling */
img[alt="Pinterest"] {
  filter: brightness(0) saturate(100%) invert(18%) sepia(14%) saturate(1036%) hue-rotate(61deg) brightness(92%) contrast(92%) !important;
  /* Approximate dark hunter green tint */
}

/* Pinterest main content container */
div[data-test-id="pinGrid"] {
  display: flex !important;
  flex-wrap: wrap !important;
  padding: 2rem !important;
  margin-left: -0.75rem !important;
  margin-right: -0.75rem !important;
  box-sizing: border-box !important;
}

/* Grid items inside Pinterest pin grid */
div[data-test-id="pinGrid"] > div {
  flex-grow: 1 !important;
  flex-shrink: 1 !important;
  flex-basis: 30% !important;
  padding-left: 0.75rem !important;
  padding-right: 0.75rem !important;
  box-sizing: border-box !important;
}

/* Responsive: 2 columns */
@media (max-width: 900px) {
  div[data-test-id="pinGrid"] > div {
    flex-basis: 48% !important;
  }
}

/* Responsive: 1 column */
@media (max-width: 600px) {
  div[data-test-id="pinGrid"] > div {
    flex-basis: 100% !important;
  }
}

/* Feminine & slim card styling */
div[data-test-id="pin"] {
  background-color: #ffffff !important;
  border-radius: 20px !important;
  box-shadow: 0 6px 14px rgba(60, 100, 75, 0.15) !important;
  overflow: hidden !important;
  border: 1px solid #d6eadd !important; /* Soft pastel green border */
  transition: box-shadow 0.3s ease, transform 0.3s ease !important;
  padding: 0.5rem !important;
}

div[data-test-id="pin"] img {
  display: block !important;
  width: 100% !important;
  height: 180px !important;
  object-fit: cover !important;
  border-radius: 15px !important;
  transition: transform 0.4s ease !important;
}

div[data-test-id="pin"]:hover {
  box-shadow: 0 10px 24px rgba(60, 100, 75, 0.25) !important;
  transform: translateY(-6px) !important;
}

div[data-test-id="pin"]:hover img {
  transform: scale(1.04) !important;
}
